// ---------------------------------------------------------------------------
// Rust tokenizer & token tree
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Delim {
    Paren,
    Bracket,
    Brace,
}

#[derive(Debug, Clone)]
enum Token {
    Ident(String, usize),
    Str(String, usize),
    Char(usize),
    Punct(char, usize),
    Group(Delim, Vec<Token>, usize),
    Other(usize),
}

impl Token {
    fn line(&self) -> usize {
        match self {
            Token::Ident(_, l)
            | Token::Str(_, l)
            | Token::Char(l)
            | Token::Punct(_, l)
            | Token::Group(_, _, l)
            | Token::Other(l) => *l,
        }
    }

    fn is_ident(&self, s: &str) -> bool {
        matches!(self, Token::Ident(id, _) if id == s)
    }

    fn is_punct(&self, c: char) -> bool {
        matches!(self, Token::Punct(ch, _) if *ch == c)
    }
}

#[derive(Debug, Clone)]
enum FlatTok {
    Ident(String, usize),
    Str(String, usize),
    Char(usize),
    Punct(char, usize),
    Open(Delim, usize),
    Close(Delim),
    Other(usize),
}

fn is_ident_start(b: u8) -> bool {
    b.is_ascii_alphabetic() || b == b'_'
}

fn is_ident_cont(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

fn lex_flat(src: &str) -> Vec<FlatTok> {
    let b = src.as_bytes();
    let len = b.len();
    let mut out = Vec::new();
    let mut i = 0usize;
    let mut line = 1usize;

    let advance_newlines = |slice: &[u8], line: &mut usize| {
        for &c in slice {
            if c == b'\n' {
                *line += 1;
            }
        }
    };

    while i < len {
        match b[i] {
            b' ' | b'\t' | b'\r' => i += 1,
            b'\n' => {
                line += 1;
                i += 1;
            }
            // Line comment.
            b'/' if b.get(i + 1) == Some(&b'/') => {
                let start = i;
                while i < len && b[i] != b'\n' {
                    i += 1;
                }
                let _ = start;
            }
            // Nested block comment.
            b'/' if b.get(i + 1) == Some(&b'*') => {
                let mut depth = 1usize;
                i += 2;
                while i < len && depth > 0 {
                    if b[i] == b'\n' {
                        line += 1;
                        i += 1;
                    } else if b[i] == b'/' && b.get(i + 1) == Some(&b'*') {
                        depth += 1;
                        i += 2;
                    } else if b[i] == b'*' && b.get(i + 1) == Some(&b'/') {
                        depth -= 1;
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
            }
            // Raw string: r"...", r#"..."#, br"...", cr"..."
            b'r' | b'b' | b'c' if is_raw_string_start(b, i) => {
                let tok_line = line;
                let mut j = i;
                if b[j] == b'b' || b[j] == b'c' {
                    j += 1;
                }
                j += 1; // skip 'r'
                let hashes = b[j..].iter().take_while(|&&c| c == b'#').count();
                j += hashes + 1; // skip hashes and opening '"'
                let content_start = j;
                let mut content_end = len;
                while j < len {
                    if b[j] == b'"'
                        && b.get(j + 1..j + 1 + hashes).is_some_and(|s| s.iter().all(|&c| c == b'#'))
                    {
                        content_end = j;
                        j += 1 + hashes;
                        break;
                    }
                    j += 1;
                }
                advance_newlines(&b[i..j], &mut line);
                let text = String::from_utf8_lossy(&b[content_start..content_end]).into_owned();
                out.push(FlatTok::Str(text, tok_line));
                i = j;
            }
            // Byte/C regular string: b"...", c"..."
            b'b' | b'c' if b.get(i + 1) == Some(&b'"') => {
                let tok_line = line;
                let (text, next) = lex_quoted_string(src, i + 1, &mut line);
                out.push(FlatTok::Str(text, tok_line));
                i = next;
            }
            // Byte char literal: b'x'
            b'b' if b.get(i + 1) == Some(&b'\'') => {
                let tok_line = line;
                let next = lex_char_lit(src, i + 1, &mut line);
                out.push(FlatTok::Char(tok_line));
                i = next;
            }
            // Regular string literal.
            b'"' => {
                let tok_line = line;
                let (text, next) = lex_quoted_string(src, i, &mut line);
                out.push(FlatTok::Str(text, tok_line));
                i = next;
            }
            // Char literal vs lifetime.
            b'\'' => {
                if let Some(next) = try_lex_char_lit(src, i, &mut line) {
                    out.push(FlatTok::Char(line));
                    i = next;
                } else {
                    out.push(FlatTok::Punct('\'', line));
                    i += 1;
                }
            }
            // Raw identifier r#ident.
            b'r' if b.get(i + 1) == Some(&b'#') && b.get(i + 2).is_some_and(|&c| is_ident_start(c)) => {
                let start = i + 2;
                let mut j = start;
                while j < len && is_ident_cont(b[j]) {
                    j += 1;
                }
                out.push(FlatTok::Ident(src[start..j].to_string(), line));
                i = j;
            }
            c if is_ident_start(c) => {
                let start = i;
                while i < len && is_ident_cont(b[i]) {
                    i += 1;
                }
                out.push(FlatTok::Ident(src[start..i].to_string(), line));
            }
            c if c.is_ascii_digit() => {
                let tok_line = line;
                while i < len && (b[i].is_ascii_alphanumeric() || b[i] == b'_') {
                    i += 1;
                }
                // Fractional part of float literal (e.g. 1.5) when followed by digit.
                if i < len && b[i] == b'.' && b.get(i + 1).is_some_and(u8::is_ascii_digit) {
                    i += 1;
                    while i < len && (b[i].is_ascii_alphanumeric() || b[i] == b'_') {
                        i += 1;
                    }
                }
                out.push(FlatTok::Other(tok_line));
            }
            b'(' => {
                out.push(FlatTok::Open(Delim::Paren, line));
                i += 1;
            }
            b')' => {
                out.push(FlatTok::Close(Delim::Paren));
                i += 1;
            }
            b'[' => {
                out.push(FlatTok::Open(Delim::Bracket, line));
                i += 1;
            }
            b']' => {
                out.push(FlatTok::Close(Delim::Bracket));
                i += 1;
            }
            b'{' => {
                out.push(FlatTok::Open(Delim::Brace, line));
                i += 1;
            }
            b'}' => {
                out.push(FlatTok::Close(Delim::Brace));
                i += 1;
            }
            c => {
                if c.is_ascii() {
                    out.push(FlatTok::Punct(c as char, line));
                    i += 1;
                } else {
                    // Non-ASCII UTF-8 char (e.g. inside an unquoted non-ident context).
                    let ch = src[i..].chars().next().unwrap();
                    out.push(FlatTok::Other(line));
                    i += ch.len_utf8();
                }
            }
        }
    }
    out
}

fn is_raw_string_start(b: &[u8], i: usize) -> bool {
    let mut j = i;
    if b[j] == b'b' || b[j] == b'c' {
        j += 1;
    }
    if b.get(j) != Some(&b'r') {
        return false;
    }
    j += 1;
    while j < b.len() && b[j] == b'#' {
        j += 1;
    }
    b.get(j) == Some(&b'"')
}

fn lex_quoted_string(src: &str, quote_pos: usize, line: &mut usize) -> (String, usize) {
    let b = src.as_bytes();
    let mut i = quote_pos + 1;
    let mut out = String::new();
    while i < b.len() {
        match b[i] {
            b'\\' => {
                if i + 1 < b.len() {
                    match b[i + 1] {
                        b'\n' => {
                            *line += 1;
                            i += 2;
                            while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\r') {
                                i += 1;
                            }
                        }
                        b'n' => {
                            out.push('\n');
                            i += 2;
                        }
                        b't' => {
                            out.push('\t');
                            i += 2;
                        }
                        b'"' => {
                            out.push('"');
                            i += 2;
                        }
                        b'\\' => {
                            out.push('\\');
                            i += 2;
                        }
                        other => {
                            out.push(other as char);
                            i += 2;
                        }
                    }
                } else {
                    i += 1;
                }
            }
            b'"' => return (out, i + 1),
            b'\n' => {
                *line += 1;
                out.push('\n');
                i += 1;
            }
            _ => {
                let ch = src[i..].chars().next().unwrap();
                out.push(ch);
                i += ch.len_utf8();
            }
        }
    }
    (out, b.len())
}

fn lex_char_lit(src: &str, quote_pos: usize, line: &mut usize) -> usize {
    try_lex_char_lit(src, quote_pos, line).unwrap_or(quote_pos + 1)
}

fn try_lex_char_lit(src: &str, quote_pos: usize, line: &mut usize) -> Option<usize> {
    let b = src.as_bytes();
    let mut i = quote_pos + 1;
    if i >= b.len() {
        return None;
    }
    if b[i] == b'\\' {
        i += 1;
        if i >= b.len() {
            return None;
        }
        // Escape: \xNN, \u{...}, or single-char escape.
        i += 1;
        while i < b.len() && b[i] != b'\'' && b[i] != b'\n' {
            i += 1;
        }
        if b.get(i) == Some(&b'\'') { Some(i + 1) } else { None }
    } else {
        let ch = src[i..].chars().next()?;
        if ch == '\'' || ch == '\n' {
            return None;
        }
        let after = i + ch.len_utf8();
        if b.get(after) == Some(&b'\'') {
            if ch == '\n' {
                *line += 1;
            }
            Some(after + 1)
        } else {
            None
        }
    }
}

fn group_tokens(flat: &[FlatTok], pos: &mut usize, expected_close: Option<Delim>) -> Vec<Token> {
    let mut out = Vec::new();
    while *pos < flat.len() {
        match &flat[*pos] {
            FlatTok::Close(d) => {
                if expected_close == Some(*d) {
                    *pos += 1;
                    break;
                }
                *pos += 1;
            }
            FlatTok::Open(d, line) => {
                let delim = *d;
                let l = *line;
                *pos += 1;
                let inner = group_tokens(flat, pos, Some(delim));
                out.push(Token::Group(delim, inner, l));
            }
            FlatTok::Ident(s, l) => {
                out.push(Token::Ident(s.clone(), *l));
                *pos += 1;
            }
            FlatTok::Str(s, l) => {
                out.push(Token::Str(s.clone(), *l));
                *pos += 1;
            }
            FlatTok::Char(l) => {
                out.push(Token::Char(*l));
                *pos += 1;
            }
            FlatTok::Punct(c, l) => {
                out.push(Token::Punct(*c, *l));
                *pos += 1;
            }
            FlatTok::Other(l) => {
                out.push(Token::Other(*l));
                *pos += 1;
            }
        }
    }
    out
}

fn tokenize(src: &str) -> Vec<Token> {
    let flat = lex_flat(src);
    let mut pos = 0;
    group_tokens(&flat, &mut pos, None)
}

// ---------------------------------------------------------------------------
// #[cfg(test)] stripping and out-of-line test module resolution
// ---------------------------------------------------------------------------

fn attr_is_cfg_test(bracket_inner: &[Token]) -> bool {
    if bracket_inner.len() < 2 || !bracket_inner[0].is_ident("cfg") {
        return false;
    }
    let Token::Group(Delim::Paren, args, _) = &bracket_inner[1] else { return false };
    cfg_expr_requires_test(args)
}

fn cfg_expr_requires_test(args: &[Token]) -> bool {
    if args.len() == 1 && args[0].is_ident("test") {
        return true;
    }
    if args.len() >= 2
        && args[0].is_ident("all")
        && let Token::Group(Delim::Paren, inner, _) = &args[1]
    {
        return split_top_level(inner, ',').into_iter().any(cfg_expr_requires_test);
    }
    false
}

fn attr_path_value(bracket_inner: &[Token]) -> Option<String> {
    if bracket_inner.len() >= 3
        && bracket_inner[0].is_ident("path")
        && bracket_inner[1].is_punct('=')
        && let Token::Str(p, _) = &bracket_inner[2]
    {
        return Some(p.clone());
    }
    None
}

/// Parse a contiguous sequence of outer attributes `# [...]` starting at `i`.
/// Returns `(next_index, has_cfg_test, path_override)`.
fn parse_outer_attrs(tokens: &[Token], mut i: usize) -> (usize, bool, Option<String>) {
    let mut has_cfg_test = false;
    let mut path_override = None;
    while i + 1 < tokens.len()
        && tokens[i].is_punct('#')
        && let Token::Group(Delim::Bracket, inner, _) = &tokens[i + 1]
    {
        if attr_is_cfg_test(inner) {
            has_cfg_test = true;
        }
        if let Some(p) = attr_path_value(inner) {
            path_override = Some(p);
        }
        i += 2;
    }
    (i, has_cfg_test, path_override)
}

/// Skip one annotated item starting at `i` (right after its outer attributes).
fn skip_item(tokens: &[Token], mut i: usize) -> usize {
    while i < tokens.len() {
        match &tokens[i] {
            Token::Punct(';', _) => return i + 1,
            Token::Group(Delim::Brace, _, _) => {
                // Consume optional trailing `;` (e.g. `const X = { ... };`).
                return if tokens.get(i + 1).is_some_and(|t| t.is_punct(';')) { i + 2 } else { i + 1 };
            }
            _ => i += 1,
        }
    }
    i
}

/// Discover out-of-line `#[cfg(test)] mod <name>;` (and `#[path = "..."]`)
/// targets declared anywhere in `tokens`.
fn find_cfg_test_mod_files(
    tokens: &[Token],
    file_path: &Path,
    out: &mut BTreeSet<PathBuf>,
    out_dirs: &mut BTreeSet<PathBuf>,
) {
    let parent_dir = file_path.parent().unwrap_or_else(|| Path::new(""));
    let stem = file_path.file_stem().and_then(|s| s.to_str()).unwrap_or("");
    let is_mod_root = matches!(stem, "lib" | "main" | "mod");

    let mut i = 0;
    while i < tokens.len() {
        if tokens[i].is_punct('#') && matches!(tokens.get(i + 1), Some(Token::Group(Delim::Bracket, _, _))) {
            let (after_attrs, has_cfg_test, path_override) = parse_outer_attrs(tokens, i);
            if has_cfg_test {
                // Skip optional visibility (`pub`, `pub(...)`) and `unsafe`.
                let mut j = after_attrs;
                if tokens.get(j).is_some_and(|t| t.is_ident("pub")) {
                    j += 1;
                    if matches!(tokens.get(j), Some(Token::Group(Delim::Paren, _, _))) {
                        j += 1;
                    }
                }
                if tokens.get(j).is_some_and(|t| t.is_ident("unsafe")) {
                    j += 1;
                }
                if tokens.get(j).is_some_and(|t| t.is_ident("mod"))
                    && let Some(Token::Ident(mod_name, _)) = tokens.get(j + 1)
                    && tokens.get(j + 2).is_some_and(|t| t.is_punct(';'))
                {
                    let mut candidates = Vec::new();
                    if let Some(rel) = path_override {
                        candidates.push(parent_dir.join(&rel));
                        if !is_mod_root {
                            candidates.push(parent_dir.join(stem).join(&rel));
                        }
                    } else if is_mod_root {
                        candidates.push(parent_dir.join(format!("{mod_name}.rs")));
                        candidates.push(parent_dir.join(mod_name).join("mod.rs"));
                    } else {
                        candidates.push(parent_dir.join(stem).join(format!("{mod_name}.rs")));
                        candidates.push(parent_dir.join(stem).join(mod_name).join("mod.rs"));
                        candidates.push(parent_dir.join(format!("{mod_name}.rs")));
                    }
                    for cand in candidates {
                        if let Ok(canon) = std::fs::canonicalize(&cand) {
                            if canon.file_name().and_then(|n| n.to_str()) == Some("mod.rs")
                                && let Some(dir) = canon.parent()
                            {
                                out_dirs.insert(dir.to_path_buf());
                            }
                            out.insert(canon);
                        }
                    }
                }
                i = skip_item(tokens, after_attrs);
                continue;
            }
            i = after_attrs;
            continue;
        }
        if let Token::Group(_, inner, _) = &tokens[i] {
            find_cfg_test_mod_files(inner, file_path, out, out_dirs);
        }
        i += 1;
    }
}

/// Remove every `#[cfg(test)]`-annotated item from `tokens`, recursively.
fn strip_cfg_test(tokens: &[Token]) -> Vec<Token> {
    let mut out = Vec::with_capacity(tokens.len());
    let mut i = 0;
    while i < tokens.len() {
        if tokens[i].is_punct('#') && matches!(tokens.get(i + 1), Some(Token::Group(Delim::Bracket, _, _))) {
            let (after_attrs, has_cfg_test, _) = parse_outer_attrs(tokens, i);
            if has_cfg_test {
                i = skip_item(tokens, after_attrs);
                continue;
            }
            // Keep non-test attributes verbatim.
            for t in &tokens[i..after_attrs] {
                out.push(t.clone());
            }
            i = after_attrs;
            continue;
        }
        match &tokens[i] {
            Token::Group(d, inner, l) => out.push(Token::Group(*d, strip_cfg_test(inner), *l)),
            other => out.push(other.clone()),
        }
        i += 1;
    }
    out
}

// ---------------------------------------------------------------------------
// Token helpers
// ---------------------------------------------------------------------------

fn split_top_level(tokens: &[Token], sep: char) -> Vec<&[Token]> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut angle = 0usize;
    for (i, t) in tokens.iter().enumerate() {
        if t.is_punct('<') {
            angle += 1;
        } else if t.is_punct('>') {
            angle = angle.saturating_sub(1);
        } else if angle == 0 && t.is_punct(sep) {
            out.push(&tokens[start..i]);
            start = i + 1;
        }
    }
    if start < tokens.len() || !out.is_empty() {
        out.push(&tokens[start..]);
    }
    out
}

fn split_call_args(tokens: &[Token]) -> Vec<&[Token]> {
    split_top_level(tokens, ',').into_iter().filter(|s| !s.is_empty()).collect()
}

/// Expected argument count in method-call form (`.method(...)`) for each
/// `rusqlite::Connection` / `Transaction` SQL-taking method. Distinguishes
/// `Connection::execute(sql, params)` (2 args) and `Connection::query_row(sql, params, f)`
/// (3 args) from already-prepared `Statement::execute(params)` (1 arg) and
/// `Statement::query_row(params, f)` (2 args).
fn expected_sql_method_args(method: &str) -> Option<usize> {
    match method {
        "prepare" | "prepare_cached" | "execute_batch" => Some(1),
        "prepare_with_flags" | "execute" => Some(2),
        "query_row" | "query_row_and_then" | "query_one" => Some(3),
        _ => None,
    }
}

/// Skip optional turbofish `::<...>` starting at `i`, returning the index after it.
fn skip_turbofish(tokens: &[Token], i: usize) -> usize {
    if tokens.get(i).is_some_and(|t| t.is_punct(':'))
        && tokens.get(i + 1).is_some_and(|t| t.is_punct(':'))
        && tokens.get(i + 2).is_some_and(|t| t.is_punct('<'))
    {
        let mut depth = 0usize;
        let mut j = i + 2;
        while j < tokens.len() {
            if tokens[j].is_punct('<') {
                depth += 1;
            } else if tokens[j].is_punct('>') {
                depth -= 1;
                if depth == 0 {
                    return j + 1;
                }
            }
            j += 1;
        }
    }
    i
}

/// Skip optional generic parameter list `<...>` starting at `i`.
fn skip_generics(tokens: &[Token], i: usize) -> usize {
    if !tokens.get(i).is_some_and(|t| t.is_punct('<')) {
        return i;
    }
    let mut depth = 0usize;
    let mut j = i;
    while j < tokens.len() {
        if tokens[j].is_punct('<') {
            depth += 1;
        } else if tokens[j].is_punct('>') {
            depth -= 1;
            if depth == 0 {
                return j + 1;
            }
        }
        j += 1;
    }
    j
}

// ---------------------------------------------------------------------------
// Direct SQL call detection
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
struct SqlCall<'a> {
    sql_arg: &'a [Token],
}

/// Collect every direct SQL call in `tokens` (recursively).
fn collect_direct_sql_calls<'a>(tokens: &'a [Token], out: &mut Vec<SqlCall<'a>>) {
    let mut i = 0;
    while i < tokens.len() {
        // 1. Method-call form: `. <sql_method> [::<...>] ( args )`
        if tokens[i].is_punct('.')
            && let Some(Token::Ident(m, _)) = tokens.get(i + 1)
            && let Some(expected) = expected_sql_method_args(m.as_str())
        {
            let after_tf = skip_turbofish(tokens, i + 2);
            if let Some(Token::Group(Delim::Paren, args, _)) = tokens.get(after_tf) {
                let parts = split_call_args(args);
                if parts.len() == expected {
                    out.push(SqlCall { sql_arg: parts[0] });
                }
                collect_direct_sql_calls(args, out);
                i = after_tf + 1;
                continue;
            }
        }

        // 2. Path-style UFCS form: `:: <sql_method> [::<...>] ( receiver, sql, ... )`
        //    (e.g. `Connection::execute(&c, sql, [])`, `Transaction::query_row(...)`).
        if tokens[i].is_punct(':')
            && tokens.get(i + 1).is_some_and(|t| t.is_punct(':'))
            && let Some(Token::Ident(m, _)) = tokens.get(i + 2)
            && let Some(expected) = expected_sql_method_args(m.as_str())
        {
            let after_tf = skip_turbofish(tokens, i + 3);
            if let Some(Token::Group(Delim::Paren, args, _)) = tokens.get(after_tf) {
                let parts = split_call_args(args);
                if parts.len() == expected + 1 {
                    out.push(SqlCall { sql_arg: parts[1] });
                }
                collect_direct_sql_calls(args, out);
                i = after_tf + 1;
                continue;
            }
        }

        // 3. `Batch::new(&conn, sql)`
        if tokens[i].is_ident("Batch")
            && tokens.get(i + 1).is_some_and(|t| t.is_punct(':'))
            && tokens.get(i + 2).is_some_and(|t| t.is_punct(':'))
            && let Some(Token::Ident(m, _)) = tokens.get(i + 3)
            && m == "new"
        {
            let after_tf = skip_turbofish(tokens, i + 4);
            if let Some(Token::Group(Delim::Paren, args, _)) = tokens.get(after_tf) {
                let parts = split_call_args(args);
                if parts.len() == 2 {
                    out.push(SqlCall { sql_arg: parts[1] });
                }
                collect_direct_sql_calls(args, out);
                i = after_tf + 1;
                continue;
            }
        }

        if let Token::Group(_, inner, _) = &tokens[i] {
            collect_direct_sql_calls(inner, out);
        }
        i += 1;
    }
}

// ---------------------------------------------------------------------------
// Behaviour-based SQL-taking helper detection (fns, methods, closures)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum HelperVis {
    Private,
    PubSuper,
    PubCrate,
    Pub,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum HelperKind {
    Fn,
    Method,
    Closure,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct DetectedHelper {
    name: String,
    vis: HelperVis,
    kind: HelperKind,
    is_pub: bool,
    line: usize,
    sql_param_indices: Vec<usize>,
}

/// Extract `{ident}` / `{ident:...}` capture names from a Rust format string literal.
fn format_captures(fmt: &str) -> Vec<String> {
    let b = fmt.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'{' {
            if b.get(i + 1) == Some(&b'{') {
                i += 2;
                continue;
            }
            i += 1;
            let start = i;
            while i < b.len() && is_ident_cont(b[i]) {
                i += 1;
            }
            if i > start && is_ident_start(b[start]) && matches!(b.get(i), Some(b'}' | b':')) {
                out.push(fmt[start..i].to_string());
            }
        } else {
            i += 1;
        }
    }
    out
}

fn tokens_contain_ident(tokens: &[Token], name: &str) -> bool {
    for (i, t) in tokens.iter().enumerate() {
        match t {
            Token::Ident(id, _) if id == name => {
                // Skip field/method accesses `x.name` and enum/module segments `Foo::name`.
                let prev_member = i > 0 && (tokens[i - 1].is_punct('.') || tokens[i - 1].is_punct(':'));
                if !prev_member {
                    return true;
                }
            }
            Token::Group(_, inner, _) if tokens_contain_ident(inner, name) => return true,
            _ => {}
        }
    }
    false
}

fn is_comparison_punct(tokens: &[Token], idx: usize) -> bool {
    // Check `==` or `!=` immediately before or after `idx`.
    let after = tokens.get(idx + 1).is_some_and(|t| t.is_punct('=') || t.is_punct('!'))
        && tokens.get(idx + 2).is_some_and(|t| t.is_punct('='));
    let before = idx >= 2
        && tokens[idx - 1].is_punct('=')
        && (tokens[idx - 2].is_punct('=') || tokens[idx - 2].is_punct('!'));
    after || before
}

fn is_non_content_method_call(tokens: &[Token], idx: usize) -> bool {
    tokens.get(idx + 1).is_some_and(|t| t.is_punct('.'))
        && matches!(
            tokens.get(idx + 2),
            Some(Token::Ident(m, _))
                if matches!(m.as_str(), "len" | "is_empty" | "is_some" | "is_none")
        )
        && matches!(tokens.get(idx + 3), Some(Token::Group(Delim::Paren, args, _)) if args.is_empty())
}

/// Does `expr` use any identifier in `tainted` as string/data content
/// (directly or via format-string capture), ignoring pure control-flow
/// conditions (`if <cond>`), equality checks (`==`/`!=`), length/presence
/// queries (`.len()`, `.is_empty()`, `.is_some()`, `.is_none()`), and struct
/// literal constructors (`Eligibility { ... }`)?
fn expr_uses_tainted(tokens: &[Token], tainted: &BTreeSet<String>) -> bool {
    let mut i = 0;
    while i < tokens.len() {
        // Skip pure boolean `if <cond>` condition tokens (but not `if let` and
        // never the `{ ... }` value branches!).
        if tokens[i].is_ident("if") && !tokens.get(i + 1).is_some_and(|t| t.is_ident("let")) {
            let mut j = i + 1;
            while j < tokens.len() && !matches!(tokens[j], Token::Group(Delim::Brace, _, _)) {
                j += 1;
            }
            i = j;
            continue;
        }

        // Skip struct literal constructors `UpperIdent { ... }` (e.g.
        // `Eligibility { org: org.to_string(), .. }`), whose fields are typed
        // data rather than SQL text.
        if let Token::Ident(ty, _) = &tokens[i]
            && ty.chars().next().is_some_and(|c| c.is_ascii_uppercase())
            && matches!(tokens.get(i + 1), Some(Token::Group(Delim::Brace, _, _)))
        {
            i += 2;
            continue;
        }

        // `format!(...)`, `write!(...)`, `writeln!(...)`, `concat!(...)`: check string captures too.
        if let Token::Ident(mac, _) = &tokens[i]
            && matches!(mac.as_str(), "format" | "write" | "writeln" | "concat")
            && tokens.get(i + 1).is_some_and(|x| x.is_punct('!'))
            && let Some(Token::Group(_, args, _)) = tokens.get(i + 2)
        {
            for arg_tok in args {
                if let Token::Str(s, _) = arg_tok {
                    for cap in format_captures(s) {
                        if tainted.contains(&cap) {
                            return true;
                        }
                    }
                }
            }
        }

        match &tokens[i] {
            Token::Ident(id, _) if tainted.contains(id) => {
                let prev_member = i > 0 && (tokens[i - 1].is_punct('.') || tokens[i - 1].is_punct(':'));
                if !prev_member && !is_non_content_method_call(tokens, i) && !is_comparison_punct(tokens, i) {
                    return true;
                }
            }
            Token::Group(_, inner, _) if expr_uses_tainted(inner, tainted) => return true,
            _ => {}
        }
        i += 1;
    }
    false
}

/// Does a parameter type carry string text (`&str`, `String`, `Cow<str>`,
/// `AsRef<str>`, `Option<&str>`, generic `S: AsRef<str>`, etc.)?
fn type_carries_string(ty: &[Token], string_generics: &BTreeSet<String>) -> bool {
    for t in ty {
        match t {
            Token::Ident(id, _) if matches!(id.as_str(), "str" | "String") => return true,
            Token::Ident(id, _) if string_generics.contains(id) => return true,
            Token::Group(_, inner, _) if type_carries_string(inner, string_generics) => return true,
            _ => {}
        }
    }
    false
}

/// Extract generic type parameter names bounded by `AsRef<str>`, `Into<String>`, `Display`, etc.
fn string_bounded_generics(header: &[Token]) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    for i in 0..header.len() {
        if let Token::Ident(g, _) = &header[i]
            && g.chars().next().is_some_and(|c| c.is_ascii_uppercase())
            && header.get(i + 1).is_some_and(|t| t.is_punct(':'))
            && !header.get(i + 2).is_some_and(|t| t.is_punct(':'))
        {
            let mut j = i + 2;
            while j < header.len() && !header[j].is_punct(',') && !header[j].is_punct('>') {
                if header[j].is_ident("str") || header[j].is_ident("String") || header[j].is_ident("Display")
                {
                    out.insert(g.clone());
                    break;
                }
                if let Token::Group(_, inner, _) = &header[j]
                    && (tokens_contain_ident(inner, "str") || tokens_contain_ident(inner, "String"))
                {
                    out.insert(g.clone());
                    break;
                }
                j += 1;
            }
        }
    }
    out
}

/// Extract candidate `(non_self_arg_index, param_name)` pairs for string-typed
/// parameters from a `fn` parameter list, plus whether the function takes `self`.
fn fn_string_params(params: &[Token], string_generics: &BTreeSet<String>) -> (Vec<(usize, String)>, bool) {
    let mut out = Vec::new();
    let mut has_self = false;
    let mut arg_idx = 0usize;
    for part in split_call_args(params) {
        if part.iter().any(|t| t.is_ident("self")) {
            has_self = true;
            continue;
        }
        if let Some(colon) = part.iter().position(|t| t.is_punct(':')) {
            let pat = &part[..colon];
            let ty = &part[colon + 1..];
            if type_carries_string(ty, string_generics) {
                for t in pat {
                    if let Token::Ident(id, _) = t
                        && id != "mut"
                        && id != "ref"
                        && id != "_"
                    {
                        out.push((arg_idx, id.clone()));
                    }
                }
            }
        }
        arg_idx += 1;
    }
    (out, has_self)
}

/// Extract candidate `(arg_index, param_name)` pairs from a closure `|...|`
/// parameter list. Untyped parameters are kept as candidates; typed parameters
/// use `type_carries_string`.
fn closure_string_params(params: &[Token]) -> Vec<(usize, String)> {
    let mut out = Vec::new();
    let empty = BTreeSet::new();
    for (arg_idx, part) in split_call_args(params).into_iter().enumerate() {
        if let Some(colon) = part.iter().position(|t| t.is_punct(':')) {
            let pat = &part[..colon];
            let ty = &part[colon + 1..];
            if type_carries_string(ty, &empty) {
                for t in pat {
                    if let Token::Ident(id, _) = t
                        && id != "mut"
                        && id != "_"
                    {
                        out.push((arg_idx, id.clone()));
                    }
                }
            }
        } else {
            for t in part {
                if let Token::Ident(id, _) = t
                    && id != "mut"
                    && id != "_"
                {
                    out.push((arg_idx, id.clone()));
                }
            }
        }
    }
    out
}

/// Propagate taint from a single parameter `seed_param` through local `let`,
/// assignments, `push_str`, and `write!` in `body`, then check whether any
/// tainted value reaches the SQL argument of a direct SQL call or the
/// SQL-taking parameter slot of a known local SQL helper.
fn param_flows_to_sql(
    body: &[Token],
    seed_param: &str,
    known_local_helpers: &BTreeMap<String, (HelperKind, BTreeSet<usize>)>,
) -> bool {
    let mut tainted: BTreeSet<String> = BTreeSet::new();
    tainted.insert(seed_param.to_string());
    for _ in 0..6 {
        let before = tainted.len();
        propagate_taint(body, &mut tainted);
        if tainted.len() == before {
            break;
        }
    }

    let mut calls = Vec::new();
    collect_direct_sql_calls(body, &mut calls);
    if calls.iter().any(|c| expr_uses_tainted(c.sql_arg, &tainted)) {
        return true;
    }
    if !known_local_helpers.is_empty() && calls_local_helper_with_tainted(body, known_local_helpers, &tainted)
    {
        return true;
    }
    false
}

fn propagate_taint(tokens: &[Token], tainted: &mut BTreeSet<String>) {
    let mut i = 0;
    while i < tokens.len() {
        // `let [mut] x [: ...] = <expr> ;` (for `if let` / `while let`, stop RHS at `{`).
        if tokens[i].is_ident("let") {
            let is_cond_let = i > 0 && (tokens[i - 1].is_ident("if") || tokens[i - 1].is_ident("while"));
            let mut j = i + 1;
            let mut vars = Vec::new();
            while j < tokens.len() && !tokens[j].is_punct('=') && !tokens[j].is_punct(';') {
                if tokens[j].is_punct(':') {
                    while j < tokens.len() && !tokens[j].is_punct('=') && !tokens[j].is_punct(';') {
                        j += 1;
                    }
                    break;
                }
                if let Token::Ident(id, _) = &tokens[j]
                    && id != "mut"
                    && id != "ref"
                    && id != "_"
                    && id.chars().next().is_some_and(|c| c.is_ascii_lowercase() || c == '_')
                {
                    vars.push(id.clone());
                }
                j += 1;
            }
            if tokens.get(j).is_some_and(|t| t.is_punct('=')) {
                let expr_start = j + 1;
                let mut expr_end = expr_start;
                while expr_end < tokens.len()
                    && !tokens[expr_end].is_punct(';')
                    && !(is_cond_let && matches!(tokens[expr_end], Token::Group(Delim::Brace, _, _)))
                {
                    expr_end += 1;
                }
                if expr_uses_tainted(&tokens[expr_start..expr_end], tainted) {
                    for v in vars {
                        tainted.insert(v);
                    }
                }
            }
        }

        // Plain reassignment `x = <expr>;` (excluding `==`, `!=`, `<=`, `>=`).
        if let Token::Ident(var, _) = &tokens[i]
            && tokens.get(i + 1).is_some_and(|t| t.is_punct('='))
            && !tokens.get(i + 2).is_some_and(|t| t.is_punct('='))
            && (i == 0 || !matches!(tokens[i - 1], Token::Punct('!' | '<' | '>' | '=', _)))
        {
            let expr_start = i + 2;
            let mut expr_end = expr_start;
            while expr_end < tokens.len() && !tokens[expr_end].is_punct(';') {
                expr_end += 1;
            }
            if expr_uses_tainted(&tokens[expr_start..expr_end], tainted) {
                tainted.insert(var.clone());
            }
        }

        // `x.push_str(<arg>)` / `x.push(<arg>)` (1-arg String/Vec append, not 2-arg `Filter::push(clause, vals)`).
        if let Token::Ident(var, _) = &tokens[i]
            && tokens.get(i + 1).is_some_and(|t| t.is_punct('.'))
            && tokens.get(i + 2).is_some_and(|t| t.is_ident("push_str") || t.is_ident("push"))
            && let Some(Token::Group(Delim::Paren, args, _)) = tokens.get(i + 3)
            && split_call_args(args).len() == 1
            && expr_uses_tainted(args, tainted)
        {
            tainted.insert(var.clone());
        }

        // `write!(x, ...)` / `writeln!(x, ...)`
        if tokens.get(i).is_some_and(|t| t.is_ident("write") || t.is_ident("writeln"))
            && tokens.get(i + 1).is_some_and(|t| t.is_punct('!'))
            && let Some(Token::Group(_, args, _)) = tokens.get(i + 2)
        {
            let parts = split_call_args(args);
            if parts.len() >= 2 && expr_uses_tainted(args, tainted) {
                for t in parts[0] {
                    if let Token::Ident(v, _) = t
                        && v != "mut"
                    {
                        tainted.insert(v.clone());
                    }
                }
            }
        }

        if let Token::Group(_, inner, _) = &tokens[i] {
            propagate_taint(inner, tainted);
        }
        i += 1;
    }
}

fn calls_local_helper_with_tainted(
    tokens: &[Token],
    helpers: &BTreeMap<String, (HelperKind, BTreeSet<usize>)>,
    tainted: &BTreeSet<String>,
) -> bool {
    for (i, t) in tokens.iter().enumerate() {
        if let Token::Ident(id, _) = t
            && let Some((kind, sql_indices)) = helpers.get(id)
            && !(i > 0 && tokens[i - 1].is_ident("fn"))
        {
            let after_tf = skip_turbofish(tokens, i + 1);
            if let Some(Token::Group(Delim::Paren, args, _)) = tokens.get(after_tf) {
                let is_dot = i > 0 && tokens[i - 1].is_punct('.');
                let is_path = i >= 2 && tokens[i - 1].is_punct(':') && tokens[i - 2].is_punct(':');
                let parts = split_call_args(args);
                let shift = match kind {
                    HelperKind::Method if is_path && !is_dot => Some(1usize),
                    HelperKind::Method if is_dot => Some(0usize),
                    HelperKind::Method => None,
                    HelperKind::Fn | HelperKind::Closure if !is_dot => Some(0usize),
                    HelperKind::Fn | HelperKind::Closure => None,
                };
                if let Some(shift) = shift {
                    for &idx in sql_indices {
                        if let Some(arg) = parts.get(idx + shift)
                            && expr_uses_tainted(arg, tainted)
                        {
                            return true;
                        }
                    }
                }
            }
        }
        if let Token::Group(_, inner, _) = t
            && calls_local_helper_with_tainted(inner, helpers, tainted)
        {
            return true;
        }
    }
    false
}

#[derive(Debug, Clone)]
struct CandidateCallable<'a> {
    name: String,
    vis: HelperVis,
    kind: HelperKind,
    is_pub: bool,
    line: usize,
    params: Vec<(usize, String)>,
    body: &'a [Token],
}

fn parse_visibility(tokens: &[Token], fn_idx: usize) -> (HelperVis, bool) {
    let mut k = fn_idx;
    while k > 0 {
        let prev = &tokens[k - 1];
        if prev.is_ident("async")
            || prev.is_ident("const")
            || prev.is_ident("unsafe")
            || prev.is_ident("extern")
        {
            k -= 1;
        } else if matches!(prev, Token::Str(_, _)) && k >= 2 && tokens[k - 2].is_ident("extern") {
            k -= 2;
        } else {
            break;
        }
    }
    if k >= 2
        && tokens[k - 2].is_ident("pub")
        && let Token::Group(Delim::Paren, inner, _) = &tokens[k - 1]
    {
        if inner.iter().any(|t| t.is_ident("super")) {
            return (HelperVis::PubSuper, false);
        }
        if inner.iter().any(|t| t.is_ident("crate")) {
            return (HelperVis::PubCrate, false);
        }
        return (HelperVis::PubSuper, false);
    }
    if k >= 1 && tokens[k - 1].is_ident("pub") {
        return (HelperVis::Pub, true);
    }
    (HelperVis::Private, false)
}

/// Collect all functions, methods, and closures in `tokens`.
fn collect_callables<'a>(
    tokens: &'a [Token],
    enclosing_fn: Option<&str>,
    in_pub_trait_impl: bool,
    out: &mut Vec<CandidateCallable<'a>>,
) {
    let mut i = 0;
    while i < tokens.len() {
        // Track `pub trait <Name> ... { ... }` so default methods on public traits
        // are recognized as public even without an explicit `pub` keyword.
        if tokens[i].is_ident("trait") {
            let (_, is_pub_trait) = parse_visibility(tokens, i);
            let mut j = i + 1;
            while j < tokens.len()
                && !matches!(tokens[j], Token::Group(Delim::Brace, _, _))
                && !tokens[j].is_punct(';')
            {
                j += 1;
            }
            if let Some(Token::Group(Delim::Brace, body, _)) = tokens.get(j) {
                collect_callables(body, enclosing_fn, is_pub_trait, out);
                i = j + 1;
                continue;
            }
        }

        // Track `impl Trait for ... { ... }` so trait impl methods can be seen as public when needed.
        if tokens[i].is_ident("impl") {
            let mut j = i + 1;
            let mut has_for = false;
            while j < tokens.len() && !matches!(tokens[j], Token::Group(Delim::Brace, _, _)) {
                if tokens[j].is_ident("for") {
                    has_for = true;
                }
                j += 1;
            }
            if let Some(Token::Group(Delim::Brace, body, _)) = tokens.get(j) {
                collect_callables(body, enclosing_fn, has_for, out);
                i = j + 1;
                continue;
            }
        }

        // `fn <name> [<generics>] ( <params> ) ... { <body> }`
        if tokens[i].is_ident("fn")
            && let Some(Token::Ident(name, line)) = tokens.get(i + 1)
        {
            let (vis, raw_pub) = parse_visibility(tokens, i);
            let is_pub = raw_pub || in_pub_trait_impl;
            let after_gen = skip_generics(tokens, i + 2);
            if let Some(Token::Group(Delim::Paren, param_toks, _)) = tokens.get(after_gen) {
                // Find body `{ ... }` before `;`.
                let mut j = after_gen + 1;
                while j < tokens.len()
                    && !matches!(tokens[j], Token::Group(Delim::Brace, _, _))
                    && !tokens[j].is_punct(';')
                {
                    j += 1;
                }
                if let Some(Token::Group(Delim::Brace, body, _)) = tokens.get(j) {
                    let header_slice = &tokens[i..j];
                    let s_gen = string_bounded_generics(header_slice);
                    let (params, has_self) = fn_string_params(param_toks, &s_gen);
                    out.push(CandidateCallable {
                        name: name.clone(),
                        vis: if in_pub_trait_impl { HelperVis::Pub } else { vis },
                        kind: if has_self { HelperKind::Method } else { HelperKind::Fn },
                        is_pub,
                        line: *line,
                        params,
                        body,
                    });
                    // Recurse into body for nested fns and closures!
                    collect_callables(body, Some(name.as_str()), false, out);
                    i = j + 1;
                    continue;
                }
            }
        }

        // Named closure: `let|const|static [mut] <name> [: ...] = [async] [move] | <params> | <body_expr> ;`
        if tokens[i].is_ident("let") || tokens[i].is_ident("const") || tokens[i].is_ident("static") {
            let mut j = i + 1;
            let mut binding: Option<(String, usize)> = None;
            if tokens.get(j).is_some_and(|t| t.is_ident("mut")) {
                j += 1;
            }
            if let Some(Token::Ident(name, line)) = tokens.get(j) {
                binding = Some((name.clone(), *line));
                j += 1;
            }
            while j < tokens.len() && !tokens[j].is_punct('=') && !tokens[j].is_punct(';') {
                j += 1;
            }
            if tokens.get(j).is_some_and(|t| t.is_punct('=')) {
                let mut k = j + 1;
                while tokens.get(k).is_some_and(|t| t.is_ident("async") || t.is_ident("move")) {
                    k += 1;
                }
                if tokens.get(k).is_some_and(|t| t.is_punct('|'))
                    && let Some(close_pipe) =
                        tokens[k + 1..].iter().position(|t| t.is_punct('|')).map(|p| k + 1 + p)
                {
                    let param_toks = &tokens[k + 1..close_pipe];
                    let body_start = close_pipe + 1;
                    let mut body_end = body_start;
                    while body_end < tokens.len() && !tokens[body_end].is_punct(';') {
                        body_end += 1;
                    }
                    let params = closure_string_params(param_toks);
                    let (name, line) = binding.unwrap_or_else(|| {
                        (format!("{}::closure", enclosing_fn.unwrap_or("<top>")), tokens[k].line())
                    });
                    out.push(CandidateCallable {
                        name,
                        vis: HelperVis::Private,
                        kind: HelperKind::Closure,
                        is_pub: false,
                        line,
                        params,
                        body: &tokens[body_start..body_end],
                    });
                    // Do not skip `;` yet so nested expressions can still be traversed if needed.
                }
            }
        }

        if let Token::Group(_, inner, _) = &tokens[i] {
            collect_callables(inner, enclosing_fn, false, out);
        }
        i += 1;
    }
}

/// Detect all SQL-taking helpers (functions, methods, closures) in one file's
/// stripped token stream, using a fixed-point pass so transitive local wrappers
/// (e.g. `name_sql` -> `names`) are caught too.
fn detect_sql_helpers(tokens: &[Token]) -> Vec<DetectedHelper> {
    let mut callables = Vec::new();
    collect_callables(tokens, None, false, &mut callables);

    let mut known: BTreeMap<String, (HelperKind, BTreeSet<usize>)> = BTreeMap::new();
    let mut found_indices: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
    for _ in 0..4 {
        let mut changed = false;
        for (idx, c) in callables.iter().enumerate() {
            let mut sql_idxs: BTreeSet<usize> = BTreeSet::new();
            for (p_idx, p_name) in &c.params {
                if param_flows_to_sql(c.body, p_name, &known) {
                    sql_idxs.insert(*p_idx);
                }
            }
            if !sql_idxs.is_empty() {
                let entry = found_indices.entry(idx).or_default();
                let before = entry.len();
                entry.extend(sql_idxs.iter().copied());
                if entry.len() != before {
                    changed = true;
                }
                let k_entry = known.entry(c.name.clone()).or_insert_with(|| (c.kind, BTreeSet::new()));
                k_entry.1.extend(sql_idxs);
            }
        }
        if !changed {
            break;
        }
    }

    found_indices
        .into_iter()
        .map(|(idx, sql_idxs)| {
            let c = &callables[idx];
            DetectedHelper {
                name: c.name.clone(),
                vis: c.vis,
                kind: c.kind,
                is_pub: c.is_pub,
                line: c.line,
                sql_param_indices: sql_idxs.into_iter().collect(),
            }
        })
        .collect()
}

// ---------------------------------------------------------------------------
// Counting calls to frozen SQL-taking helpers
// ---------------------------------------------------------------------------

fn count_helper_calls_in_tokens(tokens: &[Token], helper_name: &str, kind: HelperKind) -> usize {
    let mut count = 0usize;
    for (i, t) in tokens.iter().enumerate() {
        if let Token::Ident(id, _) = t
            && id == helper_name
        {
            // Skip `fn helper_name(` definitions.
            if i > 0 && tokens[i - 1].is_ident("fn") {
                continue;
            }
            let after_tf = skip_turbofish(tokens, i + 1);
            if matches!(tokens.get(after_tf), Some(Token::Group(Delim::Paren, _, _))) {
                let is_dot = i > 0 && tokens[i - 1].is_punct('.');
                match kind {
                    HelperKind::Method => {
                        let is_path = i >= 2 && tokens[i - 1].is_punct(':') && tokens[i - 2].is_punct(':');
                        if is_dot || is_path {
                            count += 1;
                        }
                    }
                    HelperKind::Fn | HelperKind::Closure => {
                        if !is_dot {
                            count += 1;
                        }
                    }
                }
            }
        }
        if let Token::Group(_, inner, _) = t {
            count += count_helper_calls_in_tokens(inner, helper_name, kind);
        }
    }
    count
}

// ---------------------------------------------------------------------------
// Procedure definitions & forbidden local Procedure constructors
// ---------------------------------------------------------------------------

fn count_procedure_literals(tokens: &[Token]) -> usize {
    let mut n = 0;
    for i in 0..tokens.len() {
        if tokens[i].is_ident("Procedure")
            && matches!(tokens.get(i + 1), Some(Token::Group(Delim::Brace, _, _)))
        {
            // Skip `-> [path::]Procedure { body }`, `impl [Trait for] Procedure {`, `struct Procedure {`.
            let mut start = i;
            while start >= 2 && tokens[start - 1].is_punct(':') && tokens[start - 2].is_punct(':') {
                if start >= 3 && matches!(tokens[start - 3], Token::Ident(_, _)) {
                    start -= 3;
                } else {
                    start -= 2;
                    break;
                }
            }
            let is_type_header =
                (start >= 2 && tokens[start - 2].is_punct('-') && tokens[start - 1].is_punct('>'))
                    || (start >= 1
                        && (tokens[start - 1].is_ident("impl")
                            || tokens[start - 1].is_ident("struct")
                            || tokens[start - 1].is_ident("for")));
            if !is_type_header {
                n += 1;
            }
        }
        if let Token::Group(_, inner, _) = &tokens[i] {
            n += count_procedure_literals(inner);
        }
    }
    n
}

fn tokens_mention_type(tokens: &[Token], name: &str) -> bool {
    tokens.iter().any(|t| match t {
        Token::Ident(id, _) => id == name,
        Token::Group(_, inner, _) => tokens_mention_type(inner, name),
        _ => false,
    })
}

fn find_procedure_constructors(tokens: &[Token], out: &mut Vec<(String, usize)>) {
    let mut i = 0;
    while i < tokens.len() {
        if tokens[i].is_ident("fn")
            && let Some(Token::Ident(name, line)) = tokens.get(i + 1)
        {
            let after_gen = skip_generics(tokens, i + 2);
            if matches!(tokens.get(after_gen), Some(Token::Group(Delim::Paren, _, _))) {
                let mut j = after_gen + 1;
                if tokens.get(j).is_some_and(|t| t.is_punct('-'))
                    && tokens.get(j + 1).is_some_and(|t| t.is_punct('>'))
                {
                    let ret_start = j + 2;
                    j = ret_start;
                    while j < tokens.len()
                        && !matches!(tokens[j], Token::Group(Delim::Brace, _, _))
                        && !tokens[j].is_ident("where")
                        && !tokens[j].is_punct(';')
                    {
                        j += 1;
                    }
                    let ret_slice = &tokens[ret_start..j];
                    if tokens_mention_type(ret_slice, "Procedure") {
                        out.push((name.clone(), *line));
                    }
                }
            }
        }
        if let Token::Group(_, inner, _) = &tokens[i] {
            find_procedure_constructors(inner, out);
        }
        i += 1;
    }
}

// ---------------------------------------------------------------------------
// Workspace scanner
// ---------------------------------------------------------------------------

#[derive(Debug)]
struct ScannedFile {
    krate: String,
    rel: String,
    dir: PathBuf,
    tokens: Vec<Token>,
}

fn rust_files_under(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            rust_files_under(&path, out);
        } else if path.extension().is_some_and(|e| e == "rs") {
            out.push(path);
        }
    }
}

fn scan_workspace() -> Vec<ScannedFile> {
    let crates_dir = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
    scan_crates_dir(crates_dir)
}

fn scan_crates_dir(crates_dir: &Path) -> Vec<ScannedFile> {
    let mut raw_files: Vec<(String, String, PathBuf, String)> = Vec::new();
    let mut crate_dirs: Vec<PathBuf> = std::fs::read_dir(crates_dir)
        .unwrap()
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.join("src").is_dir())
        .collect();
    crate_dirs.sort();

    for cdir in crate_dirs {
        let krate = cdir.file_name().unwrap().to_string_lossy().into_owned();
        let src_dir = cdir.join("src");
        let mut files = Vec::new();
        rust_files_under(&src_dir, &mut files);
        files.sort();
        for f in files {
            let rel = f.strip_prefix(&cdir).unwrap().to_string_lossy().replace('\\', "/");
            let text = std::fs::read_to_string(&f).unwrap();
            raw_files.push((krate.clone(), rel, f, text));
        }
    }

    // Pass 1: discover every out-of-line `#[cfg(test)] mod ...;` file/dir.
    let mut excluded_files = BTreeSet::new();
    let mut excluded_dirs = BTreeSet::new();
    let mut parsed: Vec<(String, String, PathBuf, Vec<Token>)> = Vec::with_capacity(raw_files.len());
    for (krate, rel, path, text) in raw_files {
        let toks = tokenize(&text);
        find_cfg_test_mod_files(&toks, &path, &mut excluded_files, &mut excluded_dirs);
        parsed.push((krate, rel, path, toks));
    }

    // Pass 2: drop excluded test files and strip inline `#[cfg(test)]` items.
    let mut out = Vec::new();
    for (krate, rel, path, toks) in parsed {
        if let Ok(canon) = std::fs::canonicalize(&path)
            && (excluded_files.contains(&canon) || excluded_dirs.iter().any(|d| canon.starts_with(d)))
        {
            continue;
        }
        let dir = path.parent().unwrap_or_else(|| Path::new("")).to_path_buf();
        out.push(ScannedFile { krate, rel, dir, tokens: strip_cfg_test(&toks) });
    }
    out
}

#[derive(Debug, Default)]
struct ScanReport {
    sql_counts: BTreeMap<(String, String), usize>,
    helpers: BTreeMap<(String, String, String), DetectedHelper>,
    ua_store_pub_sql_fns: BTreeMap<(String, String), DetectedHelper>,
    procedure_counts: BTreeMap<(String, String), usize>,
    procedure_constructors: Vec<(String, String, String, usize)>,
}

fn analyze(files: &[ScannedFile]) -> ScanReport {
    let mut report = ScanReport::default();

    // Step 1: detect direct SQL calls, SQL-taking helpers, procedures, and constructors.
    for f in files {
        if f.krate == "ua-store" {
            if f.rel != "src/schema.rs" {
                for h in detect_sql_helpers(&f.tokens) {
                    if h.is_pub {
                        report.ua_store_pub_sql_fns.entry((f.rel.clone(), h.name.clone())).or_insert(h);
                    }
                }
            }
            continue;
        }

        let mut direct = Vec::new();
        collect_direct_sql_calls(&f.tokens, &mut direct);
        if !direct.is_empty() {
            *report.sql_counts.entry((f.krate.clone(), f.rel.clone())).or_default() += direct.len();
        }

        for h in detect_sql_helpers(&f.tokens) {
            report.helpers.entry((f.krate.clone(), f.rel.clone(), h.name.clone())).or_insert(h);
        }

        let procs = count_procedure_literals(&f.tokens);
        if procs > 0 {
            report.procedure_counts.insert((f.krate.clone(), f.rel.clone()), procs);
        }

        let mut ctors = Vec::new();
        find_procedure_constructors(&f.tokens, &mut ctors);
        for (name, line) in ctors {
            report.procedure_constructors.push((f.krate.clone(), f.rel.clone(), name, line));
        }
    }

    // Step 2: count calls to every detected helper in its visibility scope
    // (including any frozen public SQL-taking helper exported by `ua-store`).
    let mut helper_defs: Vec<(String, String, PathBuf, DetectedHelper)> = report
        .helpers
        .iter()
        .map(|((krate, rel, _), h)| {
            let dir = files
                .iter()
                .find(|f| &f.krate == krate && &f.rel == rel)
                .map(|f| f.dir.clone())
                .unwrap_or_default();
            (krate.clone(), rel.clone(), dir, h.clone())
        })
        .collect();
    for ((rel, _), h) in &report.ua_store_pub_sql_fns {
        helper_defs.push(("ua-store".to_string(), rel.clone(), PathBuf::new(), h.clone()));
    }

    for f in files {
        if f.krate == "ua-store" {
            continue;
        }
        let mut in_scope_helpers: BTreeSet<(String, HelperKind)> = BTreeSet::new();
        for (h_crate, h_rel, h_dir, h) in &helper_defs {
            let in_scope = match h.vis {
                HelperVis::Private => &f.krate == h_crate && &f.rel == h_rel,
                HelperVis::PubSuper => &f.krate == h_crate && &f.dir == h_dir,
                HelperVis::PubCrate => &f.krate == h_crate,
                HelperVis::Pub => true,
            };
            if in_scope {
                in_scope_helpers.insert((h.name.clone(), h.kind));
            }
        }
        let mut extra = 0usize;
        for (name, kind) in &in_scope_helpers {
            extra += count_helper_calls_in_tokens(&f.tokens, name, *kind);
        }
        if extra > 0 {
            *report.sql_counts.entry((f.krate.clone(), f.rel.clone())).or_default() += extra;
        }
    }

    report
}

// ---------------------------------------------------------------------------
// Two-way drift checking
// ---------------------------------------------------------------------------

fn check_counts_baseline(
    baseline_name: &str,
    actual: &BTreeMap<(String, String), usize>,
    baseline: &[(&str, &str, usize)],
) -> Result<(), String> {
    let mut expected: BTreeMap<(String, String), usize> = BTreeMap::new();
    let mut dupes = Vec::new();
    for &(k, r, n) in baseline {
        if expected.insert((k.to_string(), r.to_string()), n).is_some() {
            dupes.push(format!("  {k}/{r}"));
        }
    }
    if !dupes.is_empty() {
        return Err(format!("duplicate entries in {baseline_name}:\n{}", dupes.join("\n")));
    }

    let mut all_keys: BTreeSet<(String, String)> = BTreeSet::new();
    all_keys.extend(actual.keys().cloned());
    all_keys.extend(expected.keys().cloned());

    let mut above = Vec::new();
    let mut below = Vec::new();
    for key in all_keys {
        let got = actual.get(&key).copied().unwrap_or(0);
        let want = expected.get(&key).copied().unwrap_or(0);
        if got > want {
            above.push(format!("  {}/{}: got {got}, baseline {want} (+{})", key.0, key.1, got - want));
        } else if got < want {
            below.push(format!("  {}/{}: got {got}, baseline {want} (-{})", key.0, key.1, want - got));
        }
    }

    if above.is_empty() && below.is_empty() {
        return Ok(());
    }

    let mut msg = format!("{baseline_name} drift detected (see docs/store.md):\n");
    if !above.is_empty() {
        msg.push_str(
            "\nAbove baseline — route new queries through ua-store repositories instead of raising the baseline:\n",
        );
        msg.push_str(&above.join("\n"));
        msg.push('\n');
    }
    if !below.is_empty() {
        msg.push_str(
            "\nBelow baseline — lower the entry in crates/ua-store/tests/sql_guard.rs in the same PR (remove it if 0):\n",
        );
        msg.push_str(&below.join("\n"));
        msg.push('\n');
    }
    Err(msg)
}

fn check_frozen_helpers(
    actual: &BTreeMap<(String, String, String), DetectedHelper>,
    baseline: &[(&str, &str, &str)],
) -> Result<(), String> {
    let expected: BTreeSet<(String, String, String)> =
        baseline.iter().map(|&(k, r, n)| (k.to_string(), r.to_string(), n.to_string())).collect();
    let got: BTreeSet<(String, String, String)> = actual.keys().cloned().collect();

    let added: Vec<String> = got
        .difference(&expected)
        .map(|k| {
            let line = actual.get(k).map(|h| h.line).unwrap_or(0);
            format!("  {}/{}:{} (L{line})", k.0, k.1, k.2)
        })
        .collect();
    let removed: Vec<String> =
        expected.difference(&got).map(|k| format!("  {}/{}:{}", k.0, k.1, k.2)).collect();

    if added.is_empty() && removed.is_empty() {
        return Ok(());
    }

    let mut msg = String::from("FROZEN_HELPERS drift detected (see docs/store.md):\n");
    if !added.is_empty() {
        msg.push_str("\nNew SQL-taking helper(s) forbidden outside ua-store:\n");
        msg.push_str(&added.join("\n"));
        msg.push('\n');
    }
    if !removed.is_empty() {
        msg.push_str(
            "\nRemoved SQL-taking helper(s) — delete these entries from FROZEN_HELPERS in the same PR:\n",
        );
        msg.push_str(&removed.join("\n"));
        msg.push('\n');
    }
    Err(msg)
}

fn check_ua_store_pub_sql_fns(
    actual: &BTreeMap<(String, String), DetectedHelper>,
    baseline: &[(&str, &str)],
) -> Result<(), String> {
    let expected: BTreeSet<(String, String)> =
        baseline.iter().map(|&(r, n)| (r.to_string(), n.to_string())).collect();
    let got: BTreeSet<(String, String)> = actual.keys().cloned().collect();

    let added: Vec<String> = got
        .difference(&expected)
        .map(|k| {
            let line = actual.get(k).map(|h| h.line).unwrap_or(0);
            format!("  ua-store/{}:{} (L{line})", k.0, k.1)
        })
        .collect();
    let removed: Vec<String> =
        expected.difference(&got).map(|k| format!("  ua-store/{}:{}", k.0, k.1)).collect();

    if added.is_empty() && removed.is_empty() {
        return Ok(());
    }

    let mut msg = String::from("FROZEN_UA_STORE_PUB_SQL_FNS drift detected (see docs/store.md):\n");
    if !added.is_empty() {
        msg.push_str("\nPublic SQL-taking function(s) forbidden in ua-store outside schema.rs:\n");
        msg.push_str(&added.join("\n"));
        msg.push('\n');
    }
    if !removed.is_empty() {
        msg.push_str(
            "\nRemoved frozen ua-store SQL fn(s) — delete from FROZEN_UA_STORE_PUB_SQL_FNS in the same PR:\n",
        );
        msg.push_str(&removed.join("\n"));
        msg.push('\n');
    }
    Err(msg)
}

fn check_procedure_constructors(actual: &[(String, String, String, usize)]) -> Result<(), String> {
    if actual.is_empty() {
        return Ok(());
    }
    let lines: Vec<String> =
        actual.iter().map(|(k, r, name, line)| format!("  {k}/{r}:{line} fn {name} -> Procedure")).collect();
    Err(format!(
        "Local Procedure-returning constructor functions are forbidden outside ua-store (reuse ua_store::org::tenant_part or move to ua-store):\n{}",
        lines.join("\n")
    ))
}

