#[test]
fn sql_calls_match_baseline() {
    let report = analyze(&scan_workspace());
    if let Err(msg) = check_counts_baseline("SQL_BASELINE", &report.sql_counts, SQL_BASELINE) {
        panic!("{msg}");
    }
}

#[test]
fn frozen_helpers_and_ua_store_pub_sql_fns() {
    let report = analyze(&scan_workspace());
    let mut errs = Vec::new();
    if let Err(msg) = check_frozen_helpers(&report.helpers, FROZEN_HELPERS) {
        errs.push(msg);
    }
    if let Err(msg) = check_ua_store_pub_sql_fns(&report.ua_store_pub_sql_fns, FROZEN_UA_STORE_PUB_SQL_FNS) {
        errs.push(msg);
    }
    assert!(errs.is_empty(), "{}", errs.join("\n"));
}

#[test]
fn procedures_match_baseline_and_no_local_constructors() {
    let report = analyze(&scan_workspace());
    let mut errs = Vec::new();
    if let Err(msg) =
        check_counts_baseline("PROCEDURE_BASELINE", &report.procedure_counts, PROCEDURE_BASELINE)
    {
        errs.push(msg);
    }
    if let Err(msg) = check_procedure_constructors(&report.procedure_constructors) {
        errs.push(msg);
    }
    assert!(errs.is_empty(), "{}", errs.join("\n"));
}

/// Helper to regenerate baselines when lowering counts or auditing the workspace:
/// `cargo test -p ua-store --test sql_guard print_generated_baselines -- --ignored --nocapture`
#[test]
#[ignore]
fn print_generated_baselines() {
    let files = scan_workspace();
    let report = analyze(&files);
    println!("=== UA_STORE_PUB_SQL_FNS ({}) ===", report.ua_store_pub_sql_fns.len());
    for ((r, name), h) in &report.ua_store_pub_sql_fns {
        println!("    ({r:?}, {name:?}), // L{} params={:?}", h.line, h.sql_param_indices);
    }
    println!("=== PROCEDURE_CONSTRUCTORS ({}) ===", report.procedure_constructors.len());
    for x in &report.procedure_constructors {
        println!("  {x:?}");
    }
    println!("=== PROCEDURE_BASELINE ({}) ===", report.procedure_counts.len());
    for ((k, r), n) in &report.procedure_counts {
        println!("    ({k:?}, {r:?}, {n}),");
    }
    println!("=== FROZEN_HELPERS ({}) ===", report.helpers.len());
    for ((k, r, name), h) in &report.helpers {
        println!(
            "    ({k:?}, {r:?}, {name:?}), // {:?} {:?} L{} params={:?}",
            h.vis, h.kind, h.line, h.sql_param_indices
        );
    }
    println!(
        "=== SQL_BASELINE ({} files, {} total) ===",
        report.sql_counts.len(),
        report.sql_counts.values().sum::<usize>()
    );
    for ((k, r), n) in &report.sql_counts {
        println!("    ({k:?}, {r:?}, {n}),");
    }
}

// ---------------------------------------------------------------------------
// Self-tests: prove every shape in docs/store.md is caught
// ---------------------------------------------------------------------------

fn write_src(root: &Path, krate: &str, rel: &str, src: &str) {
    let path = root.join(krate).join(rel);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).unwrap();
    }
    std::fs::write(path, src).unwrap();
}

#[test]
fn self_test_direct_sql_forms_and_inferred_closures() {
    let tmp = tempfile::tempdir().unwrap();
    write_src(
        tmp.path(),
        "sample-crate",
        "src/lib.rs",
        r#"
            const CONST_SQL: &str = "SELECT 1";

            fn all_forms(c: &Connection, tx: &Transaction, tbl: &str) {
                // Direct literal, format!, let, const, include_str!
                let _ = c.execute("DELETE FROM t WHERE id = ?1", [1]);
                let _ = c.prepare(&format!("SELECT * FROM {tbl}"));
                let q = "SELECT 2";
                let _ = c.prepare(q);
                let _ = c.prepare(CONST_SQL);
                let _ = c.execute_batch(include_str!("init.sql"));

                // Every counted rusqlite method variant
                let _ = c.prepare_cached("SELECT 3");
                let _ = c.prepare_with_flags("SELECT 4", flags);
                let _ = c.query_row("SELECT 5", [], |r| r.get::<_, i64>(0));
                let _ = c.query_row_and_then("SELECT 6", [], |r| r.get::<_, i64>(0));
                let _ = c.query_one("SELECT 7", [], |r| r.get::<_, i64>(0));
                let _ = Batch::new(c, "SELECT 8");

                // Path-style UFCS calls
                let _ = Connection::execute(c, "DELETE FROM t", []);
                let _ = Transaction::query_row(tx, "SELECT 9", [], |r| r.get::<_, i64>(0));

                // Already-prepared Statement::execute / query_row (1 / 2 args) are NOT double-counted
                let mut stmt = c.prepare("SELECT 10").unwrap();
                let _ = stmt.execute([1]);
                let _ = stmt.query_row([1], |r| r.get::<_, i64>(0));
            }
        "#,
    );
    // File that NEVER names rusqlite / Connection / WriteTx / Transaction (inferred closure param).
    write_src(
        tmp.path(),
        "sample-crate",
        "src/inferred.rs",
        r#"
            fn read_only(db: &Db) {
                let _ = db.read_async(|c| c.query_row("SELECT 1", [], |r| r.get::<_, i64>(0)));
            }
        "#,
    );

    let report = analyze(&scan_crates_dir(tmp.path()));
    // 13 distinct direct calls in lib.rs + `c.prepare("SELECT 10")` = 14 (Statement::execute/query_row not counted).
    assert_eq!(report.sql_counts.get(&("sample-crate".into(), "src/lib.rs".into())), Some(&14));
    assert_eq!(
        report.sql_counts.get(&("sample-crate".into(), "src/inferred.rs".into())),
        Some(&1),
        "inferred-type read_async closure without rusqlite import must be counted"
    );
}

#[test]
fn self_test_helper_shapes_and_caller_counting() {
    let tmp = tempfile::tempdir().unwrap();
    write_src(
        tmp.path(),
        "ua-tools",
        "src/helpers.rs",
        r#"
            // 1. Direct SQL wrapper
            pub(crate) fn run_sql(c: &Connection, sql: &str) {
                let _ = c.prepare(sql);
            }
            // 2. `stmt` parameter into `execute_batch`
            fn apply_stmt(c: &Connection, stmt: &str) {
                let _ = c.execute_batch(stmt);
            }
            // 3. `filter` fragment interpolated into SQL via format!
            fn rows_where(c: &Connection, filter: &str) {
                let _ = c.prepare(&format!("SELECT * FROM items WHERE {filter}"));
            }
            // 4. `table` fragment interpolated into SQL via format!
            fn count_table(c: &Connection, table: &str) {
                let _ = c.query_row(&format!("SELECT COUNT(*) FROM {table}"), [], |r| r.get::<_, i64>(0));
            }
            // 5. SQL-taking closure
            fn with_closure(c: &Connection, org: &str) {
                let count_by = |sql: &str, p: &[&str]| {
                    let _ = c.prepare(sql);
                    let _ = p;
                };
                count_by("SELECT COUNT(*) FROM a WHERE org_id = ?1", &[org]);
                count_by("SELECT COUNT(*) FROM b WHERE org_id = ?1", &[org]);
            }
            // 6. Connection trait method
            trait ConnExt {
                fn exec_text(&self, body: &str);
            }
            impl ConnExt for Connection {
                fn exec_text(&self, body: &str) {
                    let _ = self.execute(body, []);
                }
            }
            // Non-helper control: `org_id` only bound as parameter, never enters SQL text.
            fn clean_lookup(c: &Connection, org_id: &str) {
                let _ = c.query_row("SELECT 1 FROM items WHERE org_id = ?1", [org_id], |r| r.get::<_, i64>(0));
            }
            fn local_callers(c: &Connection) {
                apply_stmt(c, "CREATE TABLE x(a INT)");
                rows_where(c, "status = 'open'");
                count_table(c, "items");
                c.exec_text("DELETE FROM items");
            }
        "#,
    );
    // Cross-file caller of `pub(crate) fn run_sql` and trait method `exec_text`.
    write_src(
        tmp.path(),
        "ua-tools",
        "src/caller.rs",
        r#"
            fn call_wrappers(c: &Connection) {
                crate::helpers::run_sql(c, "SELECT 1");
                c.exec_text("DELETE FROM t");
            }
        "#,
    );
    // ua-store: forbidden `pub fn` and `pub trait` default method vs clean `pub fn` (bind-only).
    write_src(
        tmp.path(),
        "ua-store",
        "src/bad.rs",
        r#"
            pub fn leak_sql(c: &Connection, frag: &str) {
                let _ = c.prepare(&format!("SELECT * FROM t WHERE {frag}"));
            }
            pub trait BadStoreExt {
                fn exec_raw(&self, q: &str) {
                    let _ = self.execute(q, []);
                }
            }
            pub fn clean_repo_read(c: &Connection, org_id: &str, ids: &[String]) {
                let marks = vec!["?"; ids.len()].join(",");
                let sql = format!("SELECT * FROM t WHERE org_id = ?1 AND id IN ({marks})");
                let _ = c.prepare(&sql);
                let _ = org_id;
            }
            // Private helper inside ua-store is allowed (only pub fns / pub trait methods are forbidden).
            fn internal_helper(c: &Connection, sql: &str) {
                let _ = c.prepare(sql);
            }
        "#,
    );
    // ua-store/src/schema.rs is explicitly exempted from the pub fn ban.
    write_src(
        tmp.path(),
        "ua-store",
        "src/schema.rs",
        r#"
            pub fn apply_part(c: &Connection, sql: &str) {
                let _ = c.execute_batch(sql);
            }
        "#,
    );

    let report = analyze(&scan_crates_dir(tmp.path()));

    let helper_names: BTreeSet<&str> = report.helpers.keys().map(|(_, _, n)| n.as_str()).collect();
    assert_eq!(
        helper_names,
        BTreeSet::from(["run_sql", "apply_stmt", "rows_where", "count_table", "count_by", "exec_text"]),
        "every SQL-taking helper shape must be detected and bind-only clean_lookup must not be"
    );

    // Caller counting:
    // - helpers.rs has 7 direct SQL calls + 2 count_by + 1 apply_stmt + 1 rows_where + 1 count_table + 1 exec_text = 13
    assert_eq!(report.sql_counts.get(&("ua-tools".into(), "src/helpers.rs".into())), Some(&13));
    // - caller.rs has 0 direct SQL calls + 1 run_sql + 1 exec_text = 2
    assert_eq!(report.sql_counts.get(&("ua-tools".into(), "src/caller.rs".into())), Some(&2));

    let store_pubs: BTreeSet<(&str, &str)> =
        report.ua_store_pub_sql_fns.keys().map(|(r, n)| (r.as_str(), n.as_str())).collect();
    assert_eq!(
        store_pubs,
        BTreeSet::from([("src/bad.rs", "leak_sql"), ("src/bad.rs", "exec_raw")]),
        "ua-store pub fn and pub trait SQL helpers outside schema.rs must be caught, while clean_repo_read and schema.rs pass"
    );
}

#[test]
fn self_test_procedures_and_local_constructors() {
    let tmp = tempfile::tempdir().unwrap();
    write_src(
        tmp.path(),
        "ua-tools",
        "src/procs.rs",
        r#"
            pub const P: Procedure = Procedure {
                name: "x.v1",
                version: 1,
                standalone: false,
                run: |_, _| Ok(()),
                args: &[],
            };

            const fn local_ctor(name: &'static str) -> Procedure {
                Procedure { name, version: 1, standalone: false, run: |_, _| Ok(()), args: &[] }
            }

            fn qualified_ctor() -> ua_store::Procedure {
                local_ctor("y.v1")
            }
        "#,
    );
    write_src(
        tmp.path(),
        "ua-tools",
        "src/tenant_only.rs",
        r#"
            pub const TENANT: Procedure = ua_store::org::tenant_part("organization.v1.demo", &["demo"]);
        "#,
    );

    let report = analyze(&scan_crates_dir(tmp.path()));
    assert_eq!(report.procedure_counts.get(&("ua-tools".into(), "src/procs.rs".into())), Some(&2));
    assert_eq!(report.procedure_counts.get(&("ua-tools".into(), "src/tenant_only.rs".into())), None);

    let ctor_names: Vec<&str> = report.procedure_constructors.iter().map(|(_, _, n, _)| n.as_str()).collect();
    assert_eq!(ctor_names, vec!["local_ctor", "qualified_ctor"]);
    assert!(check_procedure_constructors(&report.procedure_constructors).is_err());
}

