#[test]
fn self_test_two_way_drift_reporting() {
    // 1. SQL_BASELINE / PROCEDURE_BASELINE two-way drift.
    let baseline = &[("ua-tools", "src/a.rs", 3), ("ua-tools", "src/b.rs", 2)];

    let exact = BTreeMap::from([
        (("ua-tools".into(), "src/a.rs".into()), 3),
        (("ua-tools".into(), "src/b.rs".into()), 2),
    ]);
    assert!(check_counts_baseline("SQL_BASELINE", &exact, baseline).is_ok());

    // Above baseline (existing file increased + unlisted new file > 0).
    let increased = BTreeMap::from([
        (("ua-tools".into(), "src/a.rs".into()), 4),
        (("ua-tools".into(), "src/b.rs".into()), 2),
        (("ua-tools".into(), "src/new.rs".into()), 1),
    ]);
    let err_above = check_counts_baseline("SQL_BASELINE", &increased, baseline).unwrap_err();
    assert!(err_above.contains("Above baseline"), "{err_above}");
    assert!(err_above.contains("ua-tools/src/a.rs: got 4, baseline 3 (+1)"), "{err_above}");
    assert!(err_above.contains("ua-tools/src/new.rs: got 1, baseline 0 (+1)"), "{err_above}");

    // Below baseline (decreased file + file dropped to 0).
    let decreased = BTreeMap::from([(("ua-tools".into(), "src/a.rs".into()), 1)]);
    let err_below = check_counts_baseline("SQL_BASELINE", &decreased, baseline).unwrap_err();
    assert!(err_below.contains("Below baseline"), "{err_below}");
    assert!(err_below.contains("ua-tools/src/a.rs: got 1, baseline 3 (-2)"), "{err_below}");
    assert!(err_below.contains("ua-tools/src/b.rs: got 0, baseline 2 (-2)"), "{err_below}");

    // 2. FROZEN_HELPERS two-way drift (added + removed).
    let dummy = DetectedHelper {
        name: "h".into(),
        vis: HelperVis::Private,
        kind: HelperKind::Fn,
        is_pub: false,
        line: 10,
        sql_param_indices: vec![0],
    };
    let helper_baseline = &[("ua-tools", "src/a.rs", "old_helper")];
    let helpers_added = BTreeMap::from([
        (("ua-tools".into(), "src/a.rs".into(), "old_helper".into()), dummy.clone()),
        (("ua-tools".into(), "src/a.rs".into(), "new_helper".into()), dummy.clone()),
    ]);
    let err_h_add = check_frozen_helpers(&helpers_added, helper_baseline).unwrap_err();
    assert!(err_h_add.contains("new_helper"), "{err_h_add}");

    let helpers_removed = BTreeMap::new();
    let err_h_rem = check_frozen_helpers(&helpers_removed, helper_baseline).unwrap_err();
    assert!(err_h_rem.contains("old_helper"), "{err_h_rem}");

    // 3. FROZEN_UA_STORE_PUB_SQL_FNS two-way drift (added + removed).
    let store_baseline = &[("src/ledger.rs", "query_filtered")];
    let store_added = BTreeMap::from([
        (("src/ledger.rs".into(), "query_filtered".into()), dummy.clone()),
        (("src/foo.rs".into(), "raw_sql".into()), dummy),
    ]);
    let err_s_add = check_ua_store_pub_sql_fns(&store_added, store_baseline).unwrap_err();
    assert!(err_s_add.contains("raw_sql"), "{err_s_add}");

    let err_s_rem = check_ua_store_pub_sql_fns(&BTreeMap::new(), store_baseline).unwrap_err();
    assert!(err_s_rem.contains("query_filtered"), "{err_s_rem}");
}
